/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MxTab_1.setSelectedTabIndex(1);
        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.setCode();

        // 오늘날짜로 초기화시킨다.
        const y_day = $c.ud.fn_get_search_taskdd(dts_TASK_DD, 'H');
        edt_base_dt_1.setValue(y_day);
        edt_base_dt_2.setValue(y_day);
        $c.cm.fn_com_isur(txb_ISU_CD, txb_ISU_NM);
        Grd_com_isur.style.zIndex = 30;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35606.onpageload" });
    }
};

