        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35606.xml", SCREN_PROCS_TP_CD_07);
        if (tIndex === 1) {
            $c.data.downloadGridViewExcel(grd_List, {fileName: "시가총액요건", type: "8"});
        } else if (tIndex === 2) {
            $c.data.downloadGridViewExcel(grd_List2, {fileName: "종류주식-시가총액요건", type: "8"});
        }
