    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        // DR 전환시
        if (scwin.svrGubun === "dr") {
            await $c.win.alert("DR에서 운영될때는 조회 서비스가 제공되지 않습니다.");
        } else {
            if (!await scwin.restrictDuration()) return; // 6개월 제한

            let tIndex = MxTab_1.getSelectedTabIndex();
            if (tIndex === 1) {
                await scwin.listSync();
            } else if (tIndex === 2) {
                await scwin.listSync2();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35606.btn_Search_onclick" });
    }
};

