///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setFromToDate
 * @description from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기 - 기간구분 : pTp - from 객체 이름 : pObjFrom - to 객체 이름 : pObjTo
 * @param {String} pTp pTp
 * @param {*} pObjFrom pObjFrom
 * @param {*} pObjTo pObjTo
 * @returns {void}
 * @hidden N
 */
scwin.setFromToDate = function(pTp, pObjFrom, pObjTo) {
    // 1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
    let vFrom = "";
    let vTo = pObjTo.getValue();
    // alert(vTo);

    if (vTo === '') {
        // 값이 없으면 현재일 기준으로 계산
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp === 0) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 0); // 하루(동일날짜)로

    } else if (pTp === 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7); // 일주일전

    } else if (pTp === 2) {
        // 1개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp === 3) {
        // 3개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp === 4) {
        // 6개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp === 5) {
        // 1년전
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp === 6) {
        // 2년전
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    }
    pObjFrom.setValue(vFrom);
    pObjTo.setValue(vTo);
};

/**
 * @method
 * @name restrictDuration
 * @description restrict Duration 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.restrictDuration = async function() {
    const duration = 6 * 31; // 6개월
    const start = edt_base_dt_1.getValue();
    const end = edt_base_dt_2.getValue();
    const startDate = new Date();
    const endDate = new Date();
    startDate.setYear(start.substring(0, 4));
    startDate.setMonth(start.substring(4, 6));
    startDate.setDate(start.substring(6, 8));
    endDate.setYear(end.substring(0, 4));
    endDate.setMonth(end.substring(4, 6));
    endDate.setDate(end.substring(6, 8));
    const diffTime = endDate.getTime() - startDate.getTime();
    const diffDays = diffTime / (1000 * 60 * 60 * 24);
    if (diffDays > duration) {
        const msg = " 조회기간은 " + diffDays + "일로 " + duration + "일 이하로 제한됩니다.";
        await $c.win.alert(msg);
        return false;
    }
    return true;
};
